#include <iostream>
#include <string>
#include <sstream>
#include <iomanip>

// Minh hoa quy trinh cau truc hoa ban ghi tuan tu tuong duong Fig 14.3
// Su dung luong C++17 chuan voi day du kiem tra trang thai bang explicit operator bool()
int main() {
    // Luong ghi bo nho mo phong kenh xuat tuan tu cua std::ofstream
    std::ostringstream outClientFile;

    // Kiem tra trang thai luong bang toan tu operator!
    if (!outClientFile) {
        std::cerr << "Luong xuat khong the khoi tao!\n";
        return 1;
    }

    std::cout << "Nhap cac ban ghi (account name balance), ket thuc bang EOF:\n";

    int account;
    std::string name;
    double balance;

    // Vong lap trich xuat du lieu tu cin den khi gap EOF hoac loi du lieu
    // C++17 danh gia cin thong qua explicit operator bool()
    while (std::cin >> account >> name >> balance) {
        // Ghi ban ghi co dinh dang vao luong tuan tu (giong outClientFile << ... trong Fig 14.3)
        outClientFile << account << ' ' << name << ' ' 
                      << std::fixed << std::setprecision(2) << balance << '\n';
    }

    std::cout << "\n--- Noi dung ban ghi da ghi vao luong tuan tu ---\n";
    std::cout << outClientFile.str();

    return 0;
}
